API_SUFFIX = "-api"


def seed_return_hosts(apps, schema_editor):
    """Sème `return_hosts` à partir des URL de retour réellement employées.

    Relevé du 2026-10-18 : les trois apps de prod (poker, pushit, facilitation1)
    construisent success/cancel/return_url sur leur FRONTEND_BASE_URL —
    poker.foxugly.com, pushit.foxugly.com, facilitation.foxugly.com — c'est-à-dire
    le frère `<x>.foxugly.com` de leur API `<x>-api.foxugly.com`. Ces URL ne sont
    stockées nulle part chez billing : on dérive donc le frère du `base_url`.
    Une app dont l'hôte d'API ne finit pas par `-api` ne reçoit rien et devra être
    réglée dans la console (sinon 400 au checkout). Une app déjà réglée est laissée.
    """
    App = apps.get_model("core", "App")
    for app in App.objects.all():
        if app.return_hosts:
            continue
        host = (urlparse(app.base_url).hostname or "").lower()
        first, _, rest = host.partition(".")
        if not rest or not first.endswith(API_SUFFIX) or len(first) == len(API_SUFFIX):
            continue
        app.return_hosts = [f"{first[: -len(API_SUFFIX)]}.{rest}"]
        app.save(update_fields=["return_hosts"])


